    let n = arr.length;

    // Check if the array is empty or has only one element, which are valid min heaps
    if (n <= 1) return true;

    // Iterate through the array starting from the second element
    for (let i = 1; i < n; i++) {
        // Get the parent index of the current node
        let parent = Math.floor((i - 1) / 2);

        // If the current node is greater than its parent, it violates the min heap property
        if (arr[i] > arr[parent]) return false;
    }

    // If all nodes satisfy the min heap property, return true
    return true;
}

