function Strongest_Extension(class_name, extensions) {
    let strongest = '';
    let maxStrength = -Infinity;

    for (let extension of extensions) {
        let strength = 0;
        let hasUpperCase = false;
        let hasLowerCase = false;

        for (let char of extension) {
            if (char === char.toUpperCase()) hasUpperCase = true;
            if (char === char.toLowerCase()) hasLowerCase = true;
        }

        strength = hasUpperCase ? hasUpperCase - hasLowerCase : hasLowerCase - hasUpperCase;

        if (strength > maxStrength || (strength === maxStrength && extension < strongest)) {
            maxStrength = strength;
            strongest = extension;
        }
    }

    return `${class_name}.${strongest}`;
}

