function bf(planet1, planet2) {
  const planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"];
  let start = planets.indexOf(planet1);
  let end = planets.indexOf(planet2);

  // Check if both planet names are valid
  if (start === -1 || end === -1) {
    return [];
  }

  // Ensure start is less than end for correct slicing
  if (start > end) {
    [start, end] = [end, start];
  }

  // Slice the planets array to get the planets between planet1 and planet2
  const result = planets.slice(start + 1, end);

  return result;
}

