function encode(message) {
  const vowels = 'aeiouAEIOU';
  let encodedMessage = '';

  for (let char of message) {
    if (!vowels.includes(char)) {
      encodedMessage += char;
    } else {
      let nextVowelIndex = vowels.indexOf(char) + 2;
      let nextVowel = vowels[nextVowelIndex % vowels.length];
      encodedMessage += nextVowel.toUpperCase();
    }
  }

  return encodedMessage;
}

function encode(message) {
  const vowels = 'aeiouAEIOU';
  const shiftedVowels = 'cdefghijklmnopqrstvwxyzCDEFGHIJKLMNOPQRSTUVWXYZ';

  return message.split('').map(char => {
    if (vowels.includes(char)) {
      const index = vowels.indexOf(char);
      const shiftedIndex = (index + 2) % vowels.length;
      return shiftedVowels[shiftedIndex];
    }
