function circular_shift(x, shift) {
    // Convert the integer to a string for easy manipulation
    const strX = x.toString();
    const len = strX.length;

    // If shift is greater than the number of digits, reverse the string
    if (shift > len) {
        return strX.split('').reverse().join('');
    }

    // Perform the circular shift by taking the last 'shift' characters and moving them to the front
    const shiftedPart = strX.substring(len - shift);
    const remainingPart = strX.substring(0, len - shift);

    return shiftedPart + remainingPart;
}

